import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function AddEmployeeForm({ addAddress, addEmployee, getEmployeeRoles }) {

    const [email, setEmail] = useState("");
    const [employeddate, setEmployeddate] = useState("");
    const [firstname, setFirstname] = useState("");
    const [lastname, setLastname] = useState("");
    const [position, setPosition] = useState("");
    const [role, setRole] = useState();
    const [image, setImage] = useState("");
    const [password, setPassword] = useState(""); 
    const [phone, setPhone] = useState("");

    const [postcode, setPostcode] = useState("");
    const [city, setCity] = useState("");
    const [country, setCountry] = useState("");
    const [street, setStreet] = useState("");

    const navigate = useNavigate();

    // Handle the form submission
    const handleSubmit = async (e) => {
        // Prevent the default form submission behavior
        e.preventDefault();

        // Checking if all the fields are filled
        const requiredFields = [
            firstname, lastname, position, email, employeddate, postcode, street, city, country, role, image
        ];

        // Check if any of the required fields are empty
        if (requiredFields.some(field => !field)) {
            alert("Please fill in all fields");
            return;
        };

        try {
            // Create a new address
            const newAddress = {
                street: street,
                city: city,
                postCode: postcode,
                country: country
            };

            // Add new Address to the API
            const response = await addAddress(newAddress);
            console.log("Address added:", response);

            // Extract the addressnr from the response
            const addressnr = response.addressnr; // Ensure the API returns addressnr in the response
            console.log("Address nr:", addressnr);

            // Check if addressnr is found
            if (!addressnr) {
                throw new Error("Failed to retrieve addressnr from the response");
            }

            // Create a new employee
            const newEmployee = {
                firstname: firstname,
                lastname: lastname,
                email: email,
                password: "",
                active: true,
                employeddate: employeddate,
                position: position,
                password: password,
                phone: phone,
                image: image,
                role: { rolenr: role },
                address: { addressnr: addressnr }
            };

            // Add new Employee to the database
            const employeeResponse = await addEmployee(newEmployee);
            console.log("Employee added:", employeeResponse);

            // Clear input fields
            setEmail("");
            setEmployeddate("");
            setFirstname("");
            setLastname("");
            setPosition("");
            setRole(null);
            setPostcode("");
            setCity("");
            setCountry("");
            setStreet("");
            setImage("");
            setPassword("");
            setPhone("");

            alert("Employee successfully added!");

            // Redirect to employees page after 2 seconds
            setTimeout(() => {
                navigate('/employees');
            }, 2000);
        } catch (error) {
            console.error("Error adding employee:", error);
            alert("Failed to add employee. Please try again.");
        }

    };

    // Fetch roles from getEmployeeRoles
    const [roles, setRoles] = useState([]);

    React.useEffect(() => {
        async function fetchRoles() {
            try {
                const rolesData = await getEmployeeRoles();
                setRoles(rolesData);
            } catch (error) {
                console.error("Failed to fetch roles:", error);
            }
        }
        fetchRoles();
    }, [getEmployeeRoles]);

    return (
        <>
            <h1> Add a New Employee</h1>

            <div className='formDisplayContainer'>

                <form onSubmit={handleSubmit}>

                    <div className='formField'>
                        <label>Link to Profile Image:</label>
                        <input
                            type="text"
                            className='urlInputField'
                            onChange={(e) => setImage(e.target.value)}
                            value={image}
                            placeholder='Enter image URL'
                            name='image' />
                    </div>

                    <div className='twoFieldsHolder'>

                        <div className='formField'>
                            <label>First Name: </label>
                            <input
                                type="text"
                                value={firstname}
                                onChange={(e) => setFirstname(e.target.value)}
                                className='longInputField'
                                placeholder='Enter first name'
                            />
                        </div>

                        <div className='formField'>
                            <label>Last Name: </label>
                            <input
                                type="text"
                                value={lastname}
                                onChange={(e) => setLastname(e.target.value)}
                                className='longInputField'
                                placeholder='Enter last name'
                            />
                        </div>

                    </div>
                    
                    <div className='twoFieldsHolder'>
                    
                        <div className='formField'>
                            <label>Password: </label>
                            <input
                                type="password"
                                value={password}
                                className='longInputField'
                                onChange={(e) => setPassword(e.target.value)}
                                placeholder='Enter password'
                            />
                        </div>

                        <div className='formField'>
                            <label>Employeed Date: </label>
                            <input
                                type="date"
                                value={employeddate}
                                onChange={(e) => setEmployeddate(e.target.value)}
                                className='dateInput'
                            />
                        </div>
                    
                    </div>

                    <div className='twoFieldsHolder'>

                        <div className='formField'>
                            <label>Email: </label>
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className='longInputField'
                                placeholder='Enter email address'
                            />
                        </div>

                        <div className='formField'>
                            <label>Phone: </label>
                            <input
                                type="tel"
                                value={phone}
                                onChange={(e) => setPhone(e.target.value)}
                                className='longInputField'
                                placeholder='Enter phone number'
                            />

                        </div>

                    </div>

                    <div className='twoFieldsHolder'>

                        <div className='formField'>
                            <label>Position: </label>
                            <input
                                type="text"
                                value={position}
                                onChange={(e) => setPosition(e.target.value)}
                                className='longInputField'
                                placeholder='Enter position'
                            />
                        </div>

                        <div className='formField'>
                            <label>Role: </label>
                            <select
                                value={role || ""}
                                onChange={e => setRole(e.target.value)}
                                className='formSelector'
                            >
                                <option value="" disabled>Select role</option>
                                {roles && roles.length > 0 ? (
                                    roles.map((roleOption) => (
                                        <option key={roleOption.rolenr} value={roleOption.rolenr}>
                                            {roleOption.name}
                                        </option>
                                    ))
                                ) : (
                                    <option value="" disabled>Loading roles...</option>
                                )}
                            </select>
                        </div>
                    </div>

                    <div className='formField'>
                        <label>Street: </label>
                        <input
                            type="text"
                            value={street}
                            onChange={(e) => setStreet(e.target.value)}
                            className='longInputField'
                            placeholder='Enter street address'
                        />
                    </div>

                    <div className='twoFieldsHolder'>

                        <div className='formField'>
                            <label>Post Code: </label>
                            <input
                                type="text"
                                value={postcode}
                                onChange={(e) => setPostcode(e.target.value)}
                                className='shortInputField'
                                placeholder='Enter post code'
                            />
                        </div>

                        <div className='formField'>
                            <label>City: </label>
                            <input
                                type="text"
                                value={city}
                                onChange={(e) => setCity(e.target.value)}
                                className='shortInputField'
                                placeholder='Enter city'
                            />
                        </div>

                    </div>

                    <div className='formField'>
                        <label>Country: </label>
                        <input
                            type="text"
                            value={country}
                            onChange={(e) => setCountry(e.target.value)}
                            className='shortInputField'
                            placeholder='Enter country'
                        />
                    </div>

                    <button className='addBtn' type="submit">Add Employee</button>

                </form>

            </div>

        </>
    );
}

export default AddEmployeeForm;
